/// True when `a b` is an RI pair whose flag SVG actually ships.
pub fn is_valid_flag_pair(a: u32, b: u32) -> bool {
    VALID_FLAG_PAIRS.binary_search(&(a, b)).is_ok()
}

/// Tag-sequence subdivision flags (U+1F3F4 + a tag run terminated by
/// U+E007F) whose SVG ships in the emoji pack (and mirrors to
/// `cdn.moda.app/emoji/`). Sorted — binary-searchable.
pub const VALID_TAG_SEQUENCES: &[&str] = &[
    "\u{1F3F4}\u{E0067}\u{E0062}\u{E0065}\u{E006E}\u{E0067}\u{E007F}",
    "\u{1F3F4}\u{E0067}\u{E0062}\u{E0073}\u{E0063}\u{E0074}\u{E007F}",
    "\u{1F3F4}\u{E0067}\u{E0062}\u{E0077}\u{E006C}\u{E0073}\u{E007F}",
];

/// True when `s` is a U+1F3F4 tag sequence whose flag SVG actually ships.
pub fn is_valid_tag_sequence(s: &str) -> bool {
    VALID_TAG_SEQUENCES.binary_search(&s).is_ok()
}

